insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) select id, 'https://getlasso.co/affiliate/mudwtr/', 'listing', 'affiliate', 'Lasso''s listing for the MUD WTR affiliate program (run on Impact) records a 10% per-sale commission with a 7-day cookie and a $50 payout threshold.', 'publicly_reported', now() from public.brands where name = 'MUD WTR' and not exists (select 1 from public.brand_evidence be where be.brand_id = public.brands.id and be.evidence_summary = 'Lasso''s listing for the MUD WTR affiliate program (run on Impact) records a 10% per-sale commission with a 7-day cookie and a $50 payout threshold.');
insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) select id, 'https://merchants.sovrn.com/merchants/195550/four-sigmatic-affiliate-program', 'listing', 'general', 'Sovrn''s merchant description identifies Four Sigmatic as a Finnish-founded wellness brand established in 2012 by Tero Isokauppila and friends — a long-running category pioneer.', 'publicly_reported', now() from public.brands where name = 'Four Sigmatic' and not exists (select 1 from public.brand_evidence be where be.brand_id = public.brands.id and be.evidence_summary = 'Sovrn''s merchant description identifies Four Sigmatic as a Finnish-founded wellness brand established in 2012 by Tero Isokauppila and friends — a long-running category pioneer.');
insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) select id, 'https://lovecomplement.com/pages/complement-affiliates', 'official_site', 'general', 'The page reports over 165,000 products shipped to 77,375+ customers and a fully vegan team with advisors including Dr. Joel Kahn — an established niche brand, though no creator counts are published, so saturation is recorded as unknown.', 'verified', now() from public.brands where name = 'Complement' and not exists (select 1 from public.brand_evidence be where be.brand_id = public.brands.id and be.evidence_summary = 'The page reports over 165,000 products shipped to 77,375+ customers and a fully vegan team with advisors including Dr. Joel Kahn — an established niche brand, though no creator counts are published, so saturation is recorded as unknown.');
insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) select id, 'https://podscripts.co/podcasts/marketing-happy-hour/intro-to-tiktok-shop-more-paid-media-strategies-ellie-bresler-of-beekeepers-naturals', 'listing', 'ugc_collab', 'A Beekeeper''s Naturals growth-team member describes an influencer team running a TikTok Shop affiliate creator program with ''exponential growth'' — evidence of an active, scaling creator channel, so low saturation could NOT be evidenced and saturation is recorded as unknown.', 'publicly_reported', now() from public.brands where name = 'Beekeeper''s Naturals' and not exists (select 1 from public.brand_evidence be where be.brand_id = public.brands.id and be.evidence_summary = 'A Beekeeper''s Naturals growth-team member describes an influencer team running a TikTok Shop affiliate creator program with ''exponential growth'' — evidence of an active, scaling creator channel, so low saturation could NOT be evidenced and saturation is recorded as unknown.');
insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) select id, 'https://compareepc.com/coffee-affiliate-programs/', 'listing', 'affiliate', 'CompareEPC''s network data lists Pique Life Affiliates on Impact at 10% commission, corroborating the 10% base rate from a second source.', 'publicly_reported', now() from public.brands where name = 'Pique' and not exists (select 1 from public.brand_evidence be where be.brand_id = public.brands.id and be.evidence_summary = 'CompareEPC''s network data lists Pique Life Affiliates on Impact at 10% commission, corroborating the 10% base rate from a second source.');
insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) select id, 'https://newshub.medianet.com.au/2026/11/bon-charge-launches-month-long-black-friday-sale-with-nearly-600-in-savings-on-red-light-recovery-and-wellness-tech/181172/', 'listing', 'general', 'The brand''s November 2026 Black Friday release describes Bon Charge as a premium wellness technology company with over 100 products and an affiliate program available through Skimlinks offering 15% commission.', 'publicly_reported', now() from public.brands where name = 'Bon Charge' and not exists (select 1 from public.brand_evidence be where be.brand_id = public.brands.id and be.evidence_summary = 'The brand''s November 2026 Black Friday release describes Bon Charge as a premium wellness technology company with over 100 products and an affiliate program available through Skimlinks offering 15% commission.');
insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) select id, 'https://www.pawfectlynourished.com/affiliates', 'official_site', 'general', 'The page''s own stats describe a small, early-stage service: a library of 78 recipes, plans starting at $19 and 2 species supported. No creator counts, sponsored-post counts or network creator totals were found on any fetched page, so creator saturation could NOT be evidenced as low and is recorded as unknown.', 'verified', now() from public.brands where name = 'Pawfectly Nourished' and not exists (select 1 from public.brand_evidence be where be.brand_id = public.brands.id and be.evidence_summary = 'The page''s own stats describe a small, early-stage service: a library of 78 recipes, plans starting at $19 and 2 species supported. No creator counts, sponsored-post counts or network creator totals were found on any fetched page, so creator saturation could NOT be evidenced as low and is recorded as unknown.');
